+      if(strCmd == "StartNoAckMode")
+      {
+        m_ackMode = false;
+        result = SendResponse("OK");
+      }
+      else
+      {
+        result = SendResponse("");
+      }
+    }
+    break;
+  // case 's':
+  //   {
+  //     //Deprecated for vCont
+  //     uint64_t uiAddress = -1;
+  //     if(!packet.EndOfPacket())
+  //       uiAddress = packet.Read<uint64_t>();
