+  case 'v':
+    {
+      std::string strCmd = packet.ReadString();
+      if(strCmd == "Cont")
+      {
+        switch(packet.ReadChar())
+        {
+        case '?':
+          result = SendResponse("c;s;t;r");
+          break;
+        case ';':
