+          {
+          case 'c':
+            result = OnContinue();
+            break;
+          case 's':
+            result = OnSingleStep();
+            break;
+          case 'r':
+            result = OnSingleStep();
+            break;
+          default:
+            result = -1;
+            break;
+          }
+          break;
+        default:
+          result = -1;
+          break;
+        }
+      }
+      else
+      {
+        //No other 'v' packets are supported
+        result = SendResponse("");
+      }
+    }
+    break;
+  case 'z':
+  case 'Z':
+    {
+      unsigned char type;
+
+      result = -1;
+      type = packet.Read<unsigned char>();
+      if(packet.Seek(','))
+      {
+        uint64_t uiAddress = packet.Read<uint64_t>();
+        if(packet.Seek(','))
+        {
+          uint64_t uiKind = packet.Read<uint64_t>();
+          if(cmd == 'z')
