+int GDBServer::SendError(int error)
+{
+  GDBPacket response((unsigned char*)m_respBuffer, 0, sizeof(m_respBuffer));
+  int result = response.Write("E");
+  if(result >= 0)
+  {
+    if(error < 0)
+      error = -error;
+    result = response.Write((unsigned char*)&error, sizeof(unsigned char));
+    if(result >= 0)
