+          //Send break state to debug host
+          result = Halt(HALT_WATCHPOINT, m_pHart->hartid().get(), m.GetAddress());
+          throw udb::AbortPreExecute();
+        }
+      }
+    }
+    break;
+  default:
+    break;
+  }
+  return result;
+}
